launch_source:
$ErrorActionPreference='Stop'
$root='D:\upmix\runs\exact_complex_mask_attribution_v1'
$tool='D:\upmix\tools\diag_unified_exact_mask_attribution.py'
if((Get-FileHash $tool -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'ebc1d53b73297eba264a89e385160e0ce6255c8be6b657624b6bf3fa20e99466'){throw 'CPU diagnostic source differs'}
if(Test-Path $root){throw 'Preserve prior CPU diagnostic'}
[IO.Directory]::CreateDirectory($root)|Out-Null
$wrapper=Join-Path $env:TEMP 'upmix_exact_mask_cpu_v1.ps1'
if(Test-Path $wrapper){throw 'Preserve prior wrapper'}
$content=@'
$ErrorActionPreference='Stop'
$env:CUDA_VISIBLE_DEVICES='-1'
Set-Location 'D:\upmix\tools'
$py='D:\upmix\venvs\bsrnn_reference\Scripts\python.exe'
$root='D:\upmix\runs\exact_complex_mask_attribution_v1'
try{
 $args=@('-u','D:\upmix\tools\diag_unified_exact_mask_attribution.py','--cache','D:\upmix\datasets\masknet_cache7','--reference','D:\upmix\runs\unified_capacity_continuation_v1\full40\expanded\transitions.json','--out',"$root\result")
 $p=Start-Process -FilePath $py -ArgumentList $args -PassThru -NoNewWindow -RedirectStandardOutput "$root\stdout.log" -RedirectStandardError "$root\stderr.log"
 $handle=$p.Handle
 @{worker=$p.Id;cpu_only=$true;source_sha256='ebc1d53b73297eba264a89e385160e0ce6255c8be6b657624b6bf3fa20e99466'}|ConvertTo-Json|Set-Content "$root\worker.json"
 $p.WaitForExit()
 if($p.ExitCode -ne 0 -or $null -eq $p.ExitCode){throw "CPU diagnostic exit $($p.ExitCode)"}
 @{complete=$true;exit_code=$p.ExitCode}|ConvertTo-Json|Set-Content "$root\execution.json"
}catch{@{failed=$true;reason=$_.Exception.Message}|ConvertTo-Json|Set-Content "$root\failure.json";throw}
'@
[IO.File]::WriteAllText($wrapper,$content,[Text.Encoding]::UTF8)
$r=Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{CommandLine="powershell.exe -NoProfile -ExecutionPolicy Bypass -File $wrapper"}
@{return_value=$r.ReturnValue;supervisor_pid=$r.ProcessId;root=$root;cpu_only=$true}|ConvertTo-Json -Compress
if($r.ReturnValue -ne 0){throw 'Detached CPU diagnostic launch failed'}
